var DAYS={es:['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'],en:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],pt:['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'],ms:['Ahad','Isnin','Selasa','Rabu','Khamis','Jumaat','Sabtu'],fr:['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi']};
var MON={es:['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'],en:['January','February','March','April','May','June','July','August','September','October','November','December'],pt:['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'],ms:['Januari','Februari','Mac','April','Mei','Jun','Julai','Ogos','September','Oktober','November','Disember'],fr:['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre']};
var LANGS=['es','en','pt','ms','fr'],ATTRS=['data-t','alt','title','aria-label','placeholder'],lang='es',orig={},origTitle=null;
function T(s){if(lang==='es'||!s)return s;var r=A[s];return r?r[{en:0,pt:1,ms:2,fr:3}[lang]]||s:s}
function date(d){var w=(DAYS[lang]||DAYS.es)[d.getDay()],m=(MON[lang]||MON.es)[d.getMonth()];return lang==='es'||lang==='pt'?w+', '+d.getDate()+' de '+m:lang==='ms'?w+', '+d.getDate()+' '+m:lang==='fr'?w+' '+d.getDate()+' '+m:w+', '+m+' '+d.getDate()}
function apply(l){
 if(LANGS.indexOf(l)<0)l='es';lang=l;document.documentElement.lang=l==='pt'?'pt-BR':l;
 document.querySelectorAll('[data-i18n]').forEach(function(el){var k=el.getAttribute('data-i18n');if(!(k in orig))orig[k]=el.innerHTML;var v=l==='es'?null:U[l][k];el.innerHTML=v!=null?v:orig[k]});
 document.querySelectorAll('[data-i18n-src]').forEach(function(el){el.src=el.getAttribute('data-i18n-src')+'-'+(l==='ms'?'es':l==='fr'?'en':l)+'.webp'});
 document.querySelectorAll('[data-t],[alt],[title],[aria-label],[placeholder],meta[content]').forEach(function(el){
  var o=el._o||(el._o={});(el.tagName==='META'?['content']:ATTRS).forEach(function(a){if(!el.hasAttribute(a))return;if(!(a in o))o[a]=el.getAttribute(a);el.setAttribute(a,T(o[a]))})});
 if(origTitle===null)origTitle=document.title;document.title=T(origTitle);
 document.querySelectorAll('[data-lang]').forEach(function(b){var on=b.getAttribute('data-lang')===l;b.classList.toggle('on',on);b.setAttribute('aria-checked',on)});
 var cur=document.querySelector('.lang-cur');if(cur)cur.textContent=l.toUpperCase();
 try{localStorage.setItem('lang',l)}catch(e){}
 try{document.dispatchEvent(new Event('langchange'))}catch(e){}
}
function initial(){var s=null;try{s=localStorage.getItem('lang')}catch(e){}
 var q=/[?&]lang=(es|en|pt|ms|fr)/.exec(location.search);if(q)s=q[1];
 if(LANGS.indexOf(s)>=0)return s;var n=((navigator.languages&&navigator.languages[0])||navigator.language||'es').slice(0,2).toLowerCase();
 return n==='es'?'es':n==='pt'?'pt':n==='ms'?'ms':n==='fr'?'fr':'en'}
window.I18N={T:T,date:date,set:apply,lang:function(){return lang}};
document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-lang]');if(b){e.preventDefault();apply(b.getAttribute('data-lang'))}});
// Botón del mundo: abre y cierra el menú de idiomas (se cierra al elegir, al tocar fuera o con Escape)
function menu(){var box=document.querySelector('.lang'),btn=box&&box.querySelector('.lang-btn');if(!btn)return;
 function set(o){box.classList.toggle('open',o);btn.setAttribute('aria-expanded',o)}
 btn.addEventListener('click',function(e){e.stopPropagation();set(!box.classList.contains('open'))});
 document.addEventListener('click',function(e){if(!box.contains(e.target)||(e.target.closest&&e.target.closest('[data-lang]')))set(false)});
 document.addEventListener('keydown',function(e){if(e.key==='Escape'&&box.classList.contains('open')){set(false);btn.focus()}});
}
var first=initial();
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){menu();apply(first)});else{menu();apply(first)}
lang=first;
